import{I as t}from"./index-CET_rpto.js";const n={name:"门店名称",contactName:"联系人",contactPhone:"联系电话",province:"省",city:"市",district:"区",address:"地址",lng:"经度",lat:"纬度",businessHours:"营业时间",logo:"Logo"},u={listMyStores(e){return t({url:"/sub/stores",method:"GET",params:{keyword:e}})},getStore(e){return t({url:`/sub/stores/${e}`,method:"GET"})},listStoreChanges(e){return t({url:`/stores/${e}/change-requests`,method:"GET"})},submitChange(e,r){return t({url:`/stores/${e}/change-requests`,method:"POST",data:r})},cancelChange(e){return t({url:`/stores/change-requests/${e}/cancel`,method:"POST"})},reviewList(e){return t({url:"/stores/change-requests",method:"GET",params:e})},reviewDetail(e){return t({url:`/stores/change-requests/${e}`,method:"GET"})},review(e,r,s){return t({url:`/stores/change-requests/${e}/review`,method:"POST",data:{decision:r,remark:s}})}};export{n as C,u as s};
